// Asset profile: what ONE game's adapter declares about 3D/texture assets (MULTIGAME research H-3d-games.md, section 3).
// Interfaces + a validator only. Nothing here changes behaviour; Minecraft is the first filled-in profile, every
// other game declares its own when its adapter is written. Pure, client-safe, no Nxeon imports.
import type { AdapterMaturity } from "./types";

/** How custom assets reach players. Only the first and the two workshop forms need no player action. */
export const DELIVERY_STRATEGIES = ["server-streamed", "workshop-user-publishes", "workshop-platform-publishes", "client-manual", "none"] as const;
export type DeliveryStrategy = (typeof DELIVERY_STRATEGIES)[number];

/** Which kind of worker a job needs. linux-cpu = node-2 style builds; windows-tools = Windows-only game tools; gpu = image/3D models. */
export const WORKER_CLASSES = ["linux-cpu", "windows-tools", "gpu"] as const;
export type WorkerClass = (typeof WORKER_CLASSES)[number];

/** none = nothing from the game needed; user-supplied = the user brings templates/base files; platform-licensed = Nxeon holds a licence. */
export const REQUIRED_GAME_FILES = ["none", "user-supplied", "platform-licensed"] as const;
export type RequiredGameFiles = (typeof REQUIRED_GAME_FILES)[number];

/** Channel roles of a texture set. Stored as separate lossless layers; packed into engine channels only at export. */
export const CHANNEL_ROLES = ["albedo", "normal", "roughness", "metallic", "ao", "emissive", "height", "opacity", "mask"] as const;
export type ChannelRole = (typeof CHANNEL_ROLES)[number];

export type ColorSpace = "srgb" | "linear";
export type NormalConvention = "opengl" | "directx" | "none";
export type TextureCompression = "png" | "bc1" | "bc3" | "bc5" | "bc7" | "ktx2";
export type EngineFamily = "minecraft-java" | "unreal" | "unity" | "source" | "rage" | "creation" | "hytale" | "other";

/** Where a role lands in the game's packed texture: a file name pattern and the channel(s) of it. */
export type ChannelTarget = { file: string; channels: "rgb" | "rgba" | "r" | "g" | "b" | "a" };

/** What the game owner's published terms say about hosted modding. `reviewed` is false until a human read the page. */
export type LegalPolicy = {
  policyUrl: string | null;
  /** true / false only when a reviewer read the source; otherwise "unknown" (the honest default). */
  commercialOk: boolean | "unknown";
  aiOk: boolean | "unknown";
  /** A game's own assets are never redistributed, so this is the literal false. */
  redistributeBase: false;
  monetisationRule?: string;
  attestationRequired: boolean;
  /** ISO date the policy page was last read, or null. */
  retrievedAt: string | null;
  reviewed: boolean;
};

export type AssetProfile = {
  game: string;
  engineFamily: EngineFamily;
  meshFormats: readonly string[];
  textureFormats: readonly string[];
  compression: readonly TextureCompression[];
  channelMap: Readonly<Partial<Record<ChannelRole, ChannelTarget>>>;
  normalConvention: NormalConvention;
  colorSpace: Readonly<Partial<Record<ChannelRole, ColorSpace>>>;
  /** Largest texture edge in pixels the game/adapter accepts. */
  maxTextureRes: number;
  /** reuse-template = the user's UV layout is kept; new = Cyrus may unwrap; none = the game has no UVs to manage. */
  uvRules: "reuse-template" | "new" | "none";
  skeletonPolicy: "reuse" | "own" | "none" | "forbidden";
  packaging: string;
  delivery: DeliveryStrategy;
  workerClass: WorkerClass;
  requiredGameFiles: RequiredGameFiles;
  legal: LegalPolicy;
  validators: readonly string[];
  previewShader: string;
  maturity: AdapterMaturity;
};

export type ProfileIssue = { path: string; code: string; message: string };

/** Cheap structural rules a profile must satisfy; returns issues, never throws. */
export function validateAssetProfile(p: AssetProfile): ProfileIssue[] {
  const out: ProfileIssue[] = [];
  const add = (path: string, code: string, message: string) => out.push({ path, code, message });
  if (!DELIVERY_STRATEGIES.includes(p.delivery)) add("delivery", "bad_delivery", `unknown delivery strategy ${String(p.delivery)}`);
  if (!WORKER_CLASSES.includes(p.workerClass)) add("workerClass", "bad_worker_class", `unknown worker class ${String(p.workerClass)}`);
  if (!REQUIRED_GAME_FILES.includes(p.requiredGameFiles)) add("requiredGameFiles", "bad_required_files", `unknown value ${String(p.requiredGameFiles)}`);
  if ((p.legal.redistributeBase as unknown) !== false) add("legal.redistributeBase", "must_be_false", "a game's base assets are never redistributed");
  if ((p.legal.commercialOk === true || p.legal.aiOk === true) && !p.legal.reviewed) add("legal.reviewed", "unreviewed_claim", "commercialOk/aiOk can only be true after a human reviewed the policy");
  if (p.legal.reviewed && (!p.legal.policyUrl || !p.legal.retrievedAt)) add("legal.policyUrl", "missing_source", "a reviewed policy needs its url and retrieval date");
